#
# run_sim.ps1 -- Compile the bare-metal UART1 smoke test and run it under QEMU.
#
# What it proves:
#   1. Our arm-none-eabi toolchain produces a runnable flat binary for Cortex-A9.
#   2. The Cadence UART1 register sequence (TXRST/RXRST -> MR 8N1 -> BAUDGEN 124 ->
#      BAUDDIV 6 -> CR TX_EN|RX_EN) actually emits bytes on 0xE0001000.
#   3. The system.dtb generated by sdtgen is at least not rejected by QEMU.
#
# What it does NOT prove:
#   - That the board's CH340 is wired to UART1 / MIO48-49 (QEMU does not model MIO routing).
#   - DDR timing, USB ULPI, SD boot -- those need the real board.
#
# Why '-serial null -serial stdio': QEMU's xilinx-zynq-a9 machine exposes TWO Cadence
# UARTs (uart0 @0xE0000000, uart1 @0xE0001000) as serial_hd(0) and serial_hd(1).
# With '-nographic' only the FIRST one goes to stdio, so a program printing on UART1
# looks completely silent -- that was a real 20-minute dead end. Binding the second
# chardev to stdio is what makes UART1 output visible.
#
[CmdletBinding()]
param(
    [string]$Out = (Join-Path $env:TEMP 'w7sim'),
    [int]$Seconds = 6,
    [string]$Gcc = 'D:\Xilinx\2026.1\Vitis\gnu\aarch32\nt\gcc-arm-none-eabi\bin\arm-none-eabi-gcc.exe',
    [string]$Qemu = 'D:\Xilinx\2026.1\data\emulation\qemu\comp\qemu_win\qemu-system-arm.exe'
)

$ErrorActionPreference = 'Stop'
$here = $PSScriptRoot

function Fail([string]$msg) { Write-Host "ERROR: $msg"; exit 1 }

foreach ($tool in @($Gcc, $Qemu)) {
    if (-not (Test-Path $tool)) { Fail "missing tool: $tool" }
}
foreach ($src in @('start.S', 'link.ld', 'hello_uart1.c')) {
    if (-not (Test-Path (Join-Path $here $src))) { Fail "missing source: $src" }
}

New-Item -ItemType Directory -Force $Out | Out-Null
$elf = Join-Path $Out 'hello.elf'

# --- 1) cross-compile ---------------------------------------------------------
# Note: a child process cannot write into the repository (sandboxed), so the ELF
# is deliberately built into $Out (TEMP by default), never next to the sources.
$cc = @('-mcpu=cortex-a9', '-marm', '-nostdlib', '-ffreestanding', '-O1', '-Wall',
        '-T', (Join-Path $here 'link.ld'), '-o', $elf,
        (Join-Path $here 'start.S'), (Join-Path $here 'hello_uart1.c'))
$ccOut = & $Gcc @cc 2>&1
if ($LASTEXITCODE -ne 0) { Fail "gcc failed (exit $LASTEXITCODE)`n$ccOut" }
if (-not (Test-Path $elf)) { Fail 'gcc reported success but no ELF was produced' }
Write-Host "cc  : $elf ($((Get-Item $elf).Length) B)"

# --- 2) run under QEMU -------------------------------------------------------
$ser = Join-Path $Out 'serial.txt'
$err = Join-Path $Out 'qemu_err.txt'
Remove-Item $ser, $err -ErrorAction SilentlyContinue
$args = @('-M', 'xilinx-zynq-a9', '-kernel', $elf, '-nographic',
          '-monitor', 'none', '-no-reboot',
          '-serial', 'null', '-serial', 'stdio')
$p = Start-Process -FilePath $Qemu -ArgumentList $args -RedirectStandardOutput $ser -RedirectStandardError $err -PassThru -NoNewWindow
Start-Sleep -Seconds $Seconds
if (-not $p.HasExited) { $p.Kill() }
$txt = (Get-Content $ser -Raw -ErrorAction SilentlyContinue)
$e = (Get-Content $err -Raw -ErrorAction SilentlyContinue)

# --- 3) assert ---------------------------------------------------------------
$fails = @()
if (-not $txt) { $fails += 'serial output is empty (UART1 emitted nothing)' }
if ($txt -notmatch 'UART1_SMOKE_OK') { $fails += 'marker UART1_SMOKE_OK not found' }
if ($txt -notmatch 'BAUDGEN=124 BAUDDIV=6') { $fails += 'BAUDGEN/BAUDDIV readback mismatch' }
if ($e -match 'FDT_ERR|Unable to copy device tree') { $fails += "QEMU rejected the DTB: $e" }

Write-Host '--- serial ---'
Write-Host $txt
if ($fails.Count) {
    Write-Host '--- qemu stderr ---'
    Write-Host $e
    foreach ($f in $fails) { Write-Host "FAIL: $f" }
    exit 1
}
Write-Host 'PASS: UART1 register sequence emits bytes in QEMU'
exit 0
